import test from 'node:test';
import assert from 'node:assert';
import request from 'supertest';
import { app } from '../index.js';

test('DELETE /users/:id - validation (invalid id format)', async () => {
  const res = await request(app).delete('/users/not-a-number');
  assert.strictEqual(res.status, 400);
  assert.deepStrictEqual(res.body, { error: 'invalid user id' });
});

test('DELETE /users/:id - not found', async () => {
  const res = await request(app).delete('/users/99999');
  assert.strictEqual(res.status, 404);
  assert.deepStrictEqual(res.body, { error: 'user not found' });
});

test('DELETE /users/:id - successful deletion', async () => {
  // First create a user to delete
  const postRes = await request(app).post('/users').send({ name: 'Temp User' });
  assert.strictEqual(postRes.status, 201);
  const userId = postRes.body.id;

  // Delete the user
  const delRes = await request(app).delete(`/users/${userId}`);
  assert.strictEqual(delRes.status, 200);
  assert.strictEqual(delRes.body.id, userId);
  assert.strictEqual(delRes.body.name, 'Temp User');

  // Verify user is gone
  const getRes = await request(app).get('/users');
  const found = getRes.body.find(u => u.id === userId);
  assert.strictEqual(found, undefined);
});

