import test from 'node:test';
import assert from 'node:assert';
import http from 'node:http';
import express from 'express';
import { usersRouter } from '../routes/users.js';

const app = express();
app.use(express.json());
app.use('/users', usersRouter);

function startServer() {
  return new Promise((resolve) => {
    const server = app.listen(0, () => {
      const port = server.address().port;
      resolve({ server, port });
    });
  });
}

test('DELETE /users/:id - validation and deletion', async () => {
  const { server, port } = await startServer();
  const baseUrl = `http://localhost:${port}/users`;

  try {
    // 1. Invalid ID (non-numeric)
    const res1 = await fetch(`${baseUrl}/abc`, { method: 'DELETE' });
    assert.strictEqual(res1.status, 400);
    const body1 = await res1.json();
    assert.deepStrictEqual(body1, { error: 'invalid user id' });

    // 2. Not found
    const res2 = await fetch(`${baseUrl}/99999`, { method: 'DELETE' });
    assert.strictEqual(res2.status, 404);
    const body2 = await res2.json();
    assert.deepStrictEqual(body2, { error: 'user not found' });

    // 3. Successful deletion
    // Create a user first via POST
    const createRes = await fetch(baseUrl, {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ name: 'Test Delete User' })
    });
    assert.strictEqual(createRes.status, 201);
    const newUser = await createRes.json();

    // Delete it
    const delRes = await fetch(`${baseUrl}/${newUser.id}`, { method: 'DELETE' });
    assert.strictEqual(delRes.status, 200);
    const delBody = await delRes.json();
    assert.strictEqual(delBody.id, newUser.id);
    assert.strictEqual(delBody.name, 'Test Delete User');

    // Verify it is removed
    const listRes = await fetch(baseUrl);
    const listBody = await listRes.json();
    assert.strictEqual(listBody.find(u => u.id === newUser.id), undefined);

  } finally {
    server.close();
  }
});

